import numpy as np
from collections import Counter
L=[l.split() for l in open('answer.xyz').read().split('\n')[2:] if l.strip()]
s=[l[0] for l in L]; p=np.array([[float(x) for x in l[1:]] for l in L])
print(Counter(s))
cov={'H':0.31,'C':0.76,'P':1.07,'Ir':1.41}
d=np.linalg.norm(p[:,None]-p[None],axis=2)
n=len(s); deg=[0]*n; bonds=[]
for i in range(n):
  for j in range(i+1,n):
    if d[i,j] < 1.3*(cov[s[i]]+cov[s[j]]):
      deg[i]+=1;deg[j]+=1;bonds.append((i,j))
for i in range(n):
  exp={'H':1,'C':4,'P':3,'Ir':0}[s[i]]
  if s[i]!='Ir' and deg[i]!=exp and not (s[i]=='C' and deg[i] in(3,4)) : print('check',i,s[i],deg[i])
print('Ir deg',deg[0], [(j,s[j],round(d[0,j],2)) for i,j in bonds if i==0])
"
